import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date | null;
  onChange?: (value: Date | null) => void;
};

const startOfDay = (date: Date) => new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (days: number) => {
  const base = startOfDay(new Date());
  base.setDate(base.getDate() + days);
  return base;
};

const quickOptions = [
  { key: 'today', label: 'Сегодня', offset: 0 },
  { key: 'yesterday', label: 'Вчера', offset: -1 },
  { key: 'week-ago', label: 'Неделя назад', offset: -7 },
];

export default function ReportDatePicker({ value, onChange }: ReportDatePickerProps) {
  const [internalDate, setInternalDate] = useState<Date | null>(null);
  const selected = value !== undefined ? value : internalDate;

  const applyDate = (next: Date | null) => {
    if (value === undefined) {
      setInternalDate(next);
    }
    onChange?.(next);
  };

  const isSameDay = (a: Date | null | undefined, b: Date) =>
    !!a && startOfDay(a).getTime() === b.getTime();

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12, fontFamily: 'var(--jx-font-sans)' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
        {quickOptions.map((option) => {
          const optionDate = shiftDays(option.offset);
          return (
            <JxChip
              key={option.key}
              active={isSameDay(selected, optionDate)}
              onClick={() => applyDate(optionDate)}
            >
              {option.label}
            </JxChip>
          );
        })}
      </div>
      <JxCalendar locale="ru-RU" value={selected ?? null} onValueChange={applyDate} />
    </div>
  );
}

